with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PD_BAGIC_RM_E_CODE))) as HUB_PARTY_HK
        , MD_PRE_EXI_DIS_DIS_INF as PRE_EXISTING_DISEASE_DESCRIPTION
        , cast(null as varchar) as TOBACCO_CONSUMPTION_DETAIL
        , cast(null as varchar) as FAMILY_MEDICAL_HISTORY_INDICATOR
        , 'BA_HCP_PROD_8439_CLH_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8439_clh_loader') }}
    where (nullif(trim(PD_BAGIC_RM_E_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__MEMBER_NO))) as HUB_PARTY_HK
        , cast(null as varchar) as PRE_EXISTING_DISEASE_DESCRIPTION
        , SMOKE_CONSUMP as TOBACCO_CONSUMPTION_DETAIL
        , cast(null as varchar) as FAMILY_MEDICAL_HISTORY_INDICATOR
        , 'BJAZ_EC_MEM_DTLS_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ec_mem_dtls_extn') }}
    where (nullif(trim(MEMBER_NO),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__MEMBER_NO))) as HUB_PARTY_HK
        , cast(null as varchar) as PRE_EXISTING_DISEASE_DESCRIPTION
        , cast(null as varchar) as TOBACCO_CONSUMPTION_DETAIL
        , FAMILY_HIST as FAMILY_MEDICAL_HISTORY_INDICATOR
        , 'BJAZ_HAT_ID_MEM_DETLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hat_id_mem_detls') }}
    where (nullif(trim(MEMBER_NO),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOS_ID))) as HUB_PARTY_HK
        , PAST_HIS_AILMENT as PRE_EXISTING_DISEASE_DESCRIPTION
        , cast(null as varchar) as TOBACCO_CONSUMPTION_DETAIL
        , cast(null as varchar) as FAMILY_MEDICAL_HISTORY_INDICATOR
        , 'BJAZ_HM_PREAUTH_REQUEST' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_preauth_request') }}
    where (nullif('HOSPID:' || nullif(trim(HOS_ID),''), 'HOSPID:')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then PRE_EXISTING_DISEASE_DESCRIPTION end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRE_EXISTING_DISEASE_DESCRIPTION end)) as PRE_EXISTING_DISEASE_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TOBACCO_CONSUMPTION_DETAIL end) as TOBACCO_CONSUMPTION_DETAIL,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FAMILY_MEDICAL_HISTORY_INDICATOR end) as FAMILY_MEDICAL_HISTORY_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when PRE_EXISTING_DISEASE_DESCRIPTION is not null or TOBACCO_CONSUMPTION_DETAIL is not null or FAMILY_MEDICAL_HISTORY_INDICATOR is not null
                     then md5(upper(coalesce(cast(PRE_EXISTING_DISEASE_DESCRIPTION as varchar), '') || '|' || coalesce(cast(TOBACCO_CONSUMPTION_DETAIL as varchar), '') || '|' || coalesce(cast(FAMILY_MEDICAL_HISTORY_INDICATOR as varchar), '')))
                end as SAT_PARTY_HEALTH_PROFILE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_HEALTH_PROFILE_HASHDIFF is not null
